import { AesCipher } from './aes_core.mjs';
import { ValueError } from './errors.mjs';

export class AesModeOfOperationCBC {
  constructor(keyBytes, ivBytes) {
    if (ivBytes.length !== 16) {
      throw new ValueError('initialization vector must be 16 bytes');
    }

    this.cipher = new AesCipher(keyBytes);
    this.lastCipherBlock = Uint8Array.from(ivBytes);
  }

  encrypt(plaintextBlock) {
    if (plaintextBlock.length !== 16) {
      throw new ValueError('plaintext block must be 16 bytes');
    }

    const mixed = new Uint8Array(16);
    for (let index = 0; index < 16; index += 1) {
      mixed[index] = plaintextBlock[index] ^ this.lastCipherBlock[index];
    }

    const ciphertext = this.cipher.encryptBlock(mixed);
    this.lastCipherBlock = ciphertext.slice();
    return ciphertext;
  }
}

