function needsDoubleQuotes(bytes) {
  let hasSingleQuote = false;
  let hasDoubleQuote = false;

  for (const byte of bytes) {
    if (byte === 0x27) {
      hasSingleQuote = true;
    } else if (byte === 0x22) {
      hasDoubleQuote = true;
    }
  }

  return hasSingleQuote && !hasDoubleQuote;
}

function hexByte(byte) {
  return byte.toString(16).padStart(2, '0');
}

export function pythonBytesRepr(bytes) {
  const quote = needsDoubleQuotes(bytes) ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);
  let output = `b${quote}`;

  for (const byte of bytes) {
    if (byte === 0x5c) {
      output += '\\\\';
      continue;
    }

    if (byte === quoteCode) {
      output += `\\${quote}`;
      continue;
    }

    if (byte === 0x09) {
      output += '\\t';
      continue;
    }

    if (byte === 0x0a) {
      output += '\\n';
      continue;
    }

    if (byte === 0x0d) {
      output += '\\r';
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      output += String.fromCharCode(byte);
      continue;
    }

    output += `\\x${hexByte(byte)}`;
  }

  output += quote;
  return output;
}

